from lib import *
S = SS('g33')
steps = [
    step("两个模块:app 依赖已发布的 lib v1.0.0(放在本机 file:// 代理里),本地另有一份正在修改的 lib 源码。没有 go.work 时,app 里 go run . 得到 “lib v1.0.0(代理里已发布的版本),使用 e v1.3.0”。要在 app 里试用本地的 lib,传统做法是在 app/go.mod 里加 replace example.test/lib => ../lib:go run . 得到 “lib 本地开发版(正在改的代码)”,但 app/go.mod 被改动了(多出一行 replace),它是要提交的文件。", t=tl(S(1)), done=lidx(S(1), 'app 里 go run .:', 'lib v1.0.0'), mark=lidx(S(1), '加了 replace', 'lib 本地开发版', 'replace lib => ../lib'), kv=KV([['没有 go.work', 'app 用代理里发布的 lib v1.0.0'], ['加 replace', '用上本地 lib,但改动了 app/go.mod'], ['replace 的代价', '容易把它误提交,或忘了删']], ['replace 的代价'])),
    step("go work init ./app ./lib 生成 go.work(go 1.27.1 与 use ( ./app ./lib ))。在工作区里沿用 GOFLAGS=-mod=mod 会报错:go: -mod may only be set to readonly or vendor when in workspace mode;去掉 -mod=mod 之后,app 里 go run . 得到 “lib 本地开发版(正在改的代码)”,app/go.mod 与之前完全相同;go env GOWORK 指向 go.work;go list -m all 是 app、lib、e v1.3.0;GOWORK=off 之后又回到发布的 lib v1.0.0。", t=tl(S(2)), done=lidx(S(2), 'go.work 内容', '去掉 -mod=mod'), mark=lidx(S(2), '-mod may only be set', 'app/go.mod 与之前相同', 'go env GOWORK', 'GOWORK=off'), kv=KV([['go.work', 'use ./app ./lib'], ['app/go.mod', '没有任何改动'], ['GOFLAGS=-mod=mod', '工作区模式不允许'], ['GOWORK=off', '关掉工作区,回到发布的 lib']], ['app/go.mod'])),
    step("工作区里的版本选择:app 要 e v1.3.0,lib 要 e v1.1.0。工作区里(无论在 app 还是 lib 目录)go list -m e 都是 e v1.3.0——所有 use 的模块的需求合在一起,取最大版本;在 lib 目录里 GOWORK=off,go list -m e 是 e v1.1.0。", t=tl(S(3)), done=lidx(S(3), '工作区里 go list -m e', '在 lib 目录里'), mark=lidx(S(3), 'GOWORK=off'), b=bars([['工作区里 e 的版本(v1.x)', 3, 'v1.3.0'], ['lib 单独构建时 e 的版本', 1, 'v1.1.0']], 3, done=[0], mark=[1]), kv=KV([['工作区里', 'app 与 lib 都得到 e v1.3.0'], ['lib 单独(GOWORK=off)', 'e v1.1.0'], ['含义', '在工作区里测试通过,不代表 lib 单独发布时也通过']], ['含义'])),
    step("go work edit -json 输出 {\"Go\": \"1.27.1\", \"Use\": [{\"DiskPath\": \"./app\"}, {\"DiskPath\": \"./lib\"}]};重新 go work init ./app 之后 go work use ./lib:rc=0;go work use ./nothing:go: directory nothing does not exist;go work sync:rc=0;go.work 内容仍是 use ( ./app ./lib )。", t=tl(S(4)), done=lidx(S(4), 'go work edit -json', 'go work use ./lib'), mark=lidx(S(4), 'nothing does not exist', 'go work sync'), kv=KV([['go work edit -json', '以 JSON 查看或脚本化修改'], ['go work use <目录>', '把模块加进工作区;目录不存在会报错'], ['go work sync', '把工作区的构建列表同步回各模块的 go.mod']], ['go work use <目录>'])),
    step("go mod tidy 只看单个模块:在工作区里于 app 目录运行,rc=0,app/go.mod 没有变化;GOWORK=off 构建也通过(rc=0)。", t=tl(S(5)), mark=lidx(S(5), 'go mod tidy', 'GOWORK=off 构建'), kv=KV([['工作区里的 go mod tidy', 'rc=0,app/go.mod 不变'], ['GOWORK=off 构建', 'rc=0:go.mod 本身是自洽的']], ['GOWORK=off 构建'])),
]
A = mkartg('g33', 33, 'Go,go.work,工作区,多模块,replace,真实验证,动画演示',
    '用本机 file:// 模块仓库与两个本地模块验证 go.work 工作区:不动 app/go.mod 就让 app 使用本地修改过的 lib(replace 方案要改 go.mod);go work init/use/edit/sync 的用法;工作区模式不允许 GOFLAGS=-mod=mod;工作区里版本选择取所有模块需求的并集最大值(e v1.3.0),lib 单独构建却是 e v1.1.0;GOWORK=off 回到发布的版本;go mod tidy 不受工作区影响。',
    '同时改一个应用和它依赖的库,传统做法是在应用的 go.mod 里加 replace,然后记得别提交。go.work 把“这几个目录一起开发”变成一个不进入各模块 go.mod 的本地配置。这篇用真实命令验证它的效果与几个容易踩的点。',
    [('0 行改动', '使用 go.work 后,app/go.mod 与使用前完全相同(replace 方案要多一行)'), ('e v1.3.0 / v1.1.0', '同一个 lib 在工作区里与单独构建时用到的 e 版本不同'), ('GOWORK=off', '关掉工作区,立即回到发布的 lib v1.0.0')],
    [('replace 的问题', '<p>在 <code>app/go.mod</code> 里加 <code>replace example.test/lib => ../lib</code> 能用上本地代码,但改动的是要提交的文件:路径是本机的,别人拉到就编译失败;提交前还要记得删。</p>'),
     ('go.work', '<p><code>go.work</code> 只有 <code>go</code> 版本与 <code>use</code> 列表(也可以有 <code>replace</code>),通常不提交(或者只放在 monorepo 根)。有了它,在任一 <code>use</code> 的目录里构建,都会把这些目录当作主模块的集合:<code>app</code> 直接用本地的 <code>lib</code>,两个 <code>go.mod</code> 都不动。工作区模式有自己的限制,比如不允许 <code>-mod=mod</code>(实验里的报错),要用默认的 <code>readonly</code>。</p>'),
     ('版本选择', '<p>工作区里的构建列表是所有 <code>use</code> 模块的需求合在一起做最小版本选择。所以 <code>lib</code> 自己只要 <code>e v1.1.0</code>,在工作区里却得到 <code>v1.3.0</code>(<code>app</code> 要求的)。好处是联合开发时版本一致;风险是在工作区里“能跑”不代表 <code>lib</code> 单独发布后也能跑——发布前用 <code>GOWORK=off</code> 再验证一次。</p>'),
     ('命令', '<p><code>go work use</code> 增删目录,<code>go work edit -json</code> 供脚本读取或修改,<code>go work sync</code> 把工作区算出的版本同步回各模块的 <code>go.mod</code>(这个实验里已是同步状态,没有观察到它改了什么)。</p>'),
     ('与 go mod tidy', '<p><code>go mod tidy</code> 只整理当前这一个模块的 <code>go.mod</code>,不看工作区,所以结果与有没有 <code>go.work</code> 无关。</p>')],
    steps,
    [ENV_G + '。lib v1.0.0 与 e 的两个版本放在本机 file:// 代理里(GOPROXY=file://…,GOSUMDB=off),不联网;命令输出来自真实运行;沿用 GOFLAGS=-mod=mod 的报错是实验中故意保留的',
     '没有验证:go.work 里的 replace 与 toolchain 指令、go.work.sum 的作用、工作区与 vendor 的关系、go test ./... 在工作区里的范围(只试了 go run 与 go list)、在 CI 中是否应当提交 go.work 的利弊(只是常见建议,没有验证)'],
    'go.work 工作区')
